// scripts/generate-catalog-values.ts
//
// Writes `apps/web/lib/complexes/catalog-values.generated.ts` from the pinned Catalog OpenAPI document. The
// industrial-complex value lists are the Foundation domain's (`catalog_domain` enums' `ALL`); the
// contract publishes them as `IndustrialComplex*Value` schemas, and this is the only way they enter
// the web — never copied by hand. Run `node products/gongzzang/scripts/generate-catalog-values.ts` after the pinned
// document changes; `catalog-values.test.ts` fails while the generated file disagrees with it.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const CATALOG_OPENAPI = resolve(
  here,
  "../crates/foundation-platform-client/openapi/catalog.v1.json",
);
export const OUTPUT = resolve(here, "../apps/web/lib/complexes/catalog-values.generated.ts");

/** Exported constant name → the contract schema whose `enum` it carries. */
export const VALUE_SCHEMAS: Record<string, string> = {
  COMPLEX_KINDS: "IndustrialComplexKindValue",
  COMPLEX_STATUSES: "IndustrialComplexStatusValue",
  LOT_SALES_STATUSES: "IndustrialComplexLotSalesStatusValue",
};

type OpenApiDocument = { components?: { schemas?: Record<string, { enum?: unknown[] }> } };

/** The values each schema lists, failing when the contract no longer publishes one. */
export function valueLists(document: OpenApiDocument): Record<string, unknown[]> {
  return Object.fromEntries(
    Object.entries(VALUE_SCHEMAS).map(([name, schema]) => {
      const values = document.components?.schemas?.[schema]?.enum;
      if (!Array.isArray(values) || values.length === 0)
        throw new Error(`${schema} publishes no enum in the Catalog OpenAPI document`);
      return [name, values];
    }),
  );
}

/** One constant, laid out the way the repository formatter lays it out (one line when it fits). */
function renderList(name: string, values: unknown[]): string {
  const quoted = values.map((value) => JSON.stringify(value));
  const line = `export const ${name} = [${quoted.join(", ")}] as const;`;
  if (line.length <= 100) return `${line}\n`;
  return `export const ${name} = [\n${quoted.map((value) => `  ${value},\n`).join("")}] as const;\n`;
}

/** The generated module's full text for `document`. */
export function render(document: OpenApiDocument): string {
  const body = Object.entries(valueLists(document))
    .map(([name, values]) => renderList(name, values))
    .join("\n");
  return [
    "// GENERATED by products/gongzzang/scripts/generate-catalog-values.ts from the pinned Catalog OpenAPI document.",
    "// Do not edit: change the Foundation domain enum, re-export the document, and regenerate.",
    "",
    body,
  ].join("\n");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUTPUT, render(JSON.parse(readFileSync(CATALOG_OPENAPI, "utf8"))));
  console.info(`[catalog-values] wrote ${OUTPUT}`);
}
